import {ATLAS} from '../content/atlas.js';
import {CLASSES,STAT_KEYS,EFFECTS,BRANCH_RULES} from '../content/classes.js';import {ZONES,REGION,ITEM_TEMPLATES,ENEMIES} from '../content/region.js';
import {makeHero,derive,xpNeeded,compare,uid,lineOfSight} from '../core/rules.js';import {LocalSession,RemoteSession} from '../net/client.js';import {loadSave,getLegacy,migrateV1,saveLocal,validateImported} from '../core/storage.js';import {launchScene} from '../render/scene.js';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let session=null,selectedClass='swordsman',panel=null,lastHUD=0,toastTimer,logs=[],joystick={x:0,y:0},serverAvailable=false;let sceneHandle;
const hero=()=>session?.state.players[session.id];
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200)}
function command(type,data={}){if(!session)return;let r=session.command(type,data);if(r.error)toast(r.error);return r;}
function artStyle(classId,col=0){let row=CLASSES[classId].atlas,sheet=row>3?'heroes-extra-v2.png':'heroes-v2.png';let meta=ATLAS[row>3?'extra':'heroes'];if(row>3)row-=4;let x=meta.cols[col],y=meta.rows[row],w=meta.cols[col+1]-x,ht=meta.rows[row+1]-y;return`background-image:url(assets/${sheet});background-size:${meta.width/w*100}% ${meta.height/ht*100}%;background-position:${x/(meta.width-w)*100}% ${y/(meta.height-ht)*100}%`}
function show(title,html,kicker='ХРОНІКИ ОБЕРЕГУ'){ $('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal-kicker').textContent=kicker;if(!$('modal').open)$('modal').showModal();$('modal').classList.toggle('creating',panel==='create');}
function close(){$('modal').close();panel=null;}
function choose(){panel='create';let c=CLASSES[selectedClass],saved=loadSave(),legacy=getLegacy();show('Оберіть свою історію',`<p class="muted">Один персонаж. Ваш клас, ваш шлях. Пригода починається у Вербовій слободі.</p><div class="class-grid">${Object.entries(CLASSES).map(([id,c])=>`<button class="class-card ${id===selectedClass?'selected':''}" data-class="${id}" aria-pressed="${id===selectedClass}"><span class="preview-art" style="${artStyle(id)}"></span><b>${c.name}</b><small>${c.role}</small></button>`).join('')}</div><div class="creation-summary"><div><p><b>${c.name}</b> · ${c.role}</p><p class="muted">${c.skills.map(s=>s.icon+' '+s.name).join(' · ')}</p><p class="small">Спеціалізації: 20 / 40 / 60 · фінальна форма: 85</p></div><div><label for="character-name">Ім’я персонажа</label><div class="field"><input id="character-name" maxlength="22" value="${escape(sessionStorage.getItem('vyriy-name')||'Мандрівник')}" aria-label="Ім’я персонажа"></div></div></div>${legacy&&!saved?'<label class="checkline"><input id="migrate-legacy" type="checkbox" checked> Перенести прогрес першої версії. Старе збереження залишиться.</label>':''}<button id="start-local" class="btn">Почати локальну пригоду →</button>${saved?'<button id="continue-local" class="btn secondary">Продовжити збережену гру</button>':''}<button id="start-coop-menu" class="btn secondary">Кооператив · до 8 гравців</button><p class="small muted">Локальний режим не є MMO. У мережевому режимі один гравець контролює лише свого персонажа; сервер обчислює бій, нагороди та спільні переходи.</p>`,'В И Р І Й · ВЕРБОВЕ ПРИКОРДОННЯ');}
function startLocal(continuing=false){let saved=continuing?loadSave():null;if(saved){for(let p of Object.values(saved.players)){p.online=true;p.path=[];p.auto=false;}session=new LocalSession(saved);close();return;}let name=$('character-name')?.value.trim()||sessionStorage.getItem('vyriy-name')||'Мандрівник';if(!/^[\p{L}\p{N} ’'-]{1,22}$/u.test(name)){toast('Ім’я: 1–22 літери або цифри');return}sessionStorage.setItem('vyriy-name',name);let h=$('migrate-legacy')?.checked?migrateV1(getLegacy(),selectedClass,name):makeHero(selectedClass,name);session=new LocalSession(null,h);session.save();close();toast('WASD або дотик — рух. Поговоріть із Берегинею.');}
function nearestObject(){let h=hero();if(!h)return null;return ZONES[session.state.zone].objects.filter(o=>Math.hypot(h.x-o.x-.5,h.y-o.y-.5)<2.8&&lineOfSight(session.state.zone,h,{x:o.x+.5,y:o.y+.5},session.state.flags)).sort((a,b)=>Math.hypot(h.x-a.x,h.y-a.y)-Math.hypot(h.x-b.x,h.y-b.y))[0];}
function interact(o){if(!o)return toast('Поруч немає об’єкта. Підійдіть до NPC, скрині або входу.');let r=command('interact',{id:o.id});if(r?.error)return;if(o.kind==='merchant')open('shop');else if(o.kind==='npc'){panel='dialogue';show(o.name,`<p class="dialogue">«${escape(o.dialogue)}»</p><button class="btn" data-close>Вирушаю →</button>`);}}
function action(id){if(!session)return;if(id==='attack')command('attack');if(id==='skill0'||id==='skill1')command('skill',{index:id==='skill0'?0:1});if(id==='potion'){let item=hero().inventory.find(i=>i.template==='potion');if(item)command('use',{id:item.id});else toast('Червоні зілля закінчилися')}if(id==='interact')interact(nearestObject());}
function itemCards(items,shop=false){let h=hero();return items.map(item=>{let t=ITEM_TEMPLATES[item.template],equipped=Object.values(h.equipment).includes(item.id),delta=['weapon','armor'].includes(t.kind)?compare(h,item.id):null;let changes=delta?Object.entries(delta).filter(([k,v])=>Math.abs(v)>.01).map(([k,v])=>`<span class="${v<0?'negative':''}">${k.toUpperCase()} ${v>0?'+':''}${v.toFixed(k==='interval'?2:0)}${k==='interval'?' с':''}</span>`).join(' · '):'';return`<article class="card"><span class="icon">${t.icon||'◆'}</span> ${equipped?'<span class="tag">Споряджено</span>':''}<h3>${t.name}${item.quality?' +'+item.quality:''}</h3><p>${t.desc||'Матеріал для торгівлі.'}</p><p>Вимоги: рів. ${t.requirements.level}${t.requirements.classes?' · '+t.requirements.classes.map(c=>CLASSES[c].name).join(', '):''}<br>${Object.entries(t.stats).map(([k,v])=>k.toUpperCase()+' +'+v).join(' · ')}${item.card?' · руна +3 ATK/MATK':''}</p>${changes?`<p class="comparison">Зміна при заміні: ${changes}</p>`:''}<small class="item-id">ID ${escape(item.id)}<br>Власник: ${escape(h.name)}</small><div>${shop?`<button class="btn" data-buy="${item.template}">Купити · ${Math.ceil(t.price*(h.classId==='merchant'?.9:1))} Z</button>`:t.kind==='consumable'?`<button class="btn" data-use="${escape(item.id)}">Використати</button>`:['weapon','armor'].includes(t.kind)?`<button class="btn" data-equip="${escape(item.id)}" ${equipped?'disabled':''}>Спорядити</button>`:t.kind==='card'?`<button class="btn" data-socket="${escape(item.id)}">У зброю</button>`:t.kind==='material'&&panel==='shop'?`<button class="btn secondary" data-sell="${escape(item.id)}">Продати · ${t.price} Z</button>`:''}${session.mode==='online'&&!equipped?`<button class="btn secondary" data-offer="${escape(item.id)}">Передати…</button>`:''}</div></article>`}).join('');}
function open(name){panel=name;let h=hero(),s=session?.state;if(name==='create'){choose();return;}if(name==='coop'&&!h){showCoop();return;}if(!h)return;let d=derive(h),title='',html='';switch(name){case'hero':title=h.name+' · '+CLASSES[h.classId].name;html=`<div class="notice">Рівень ${h.level} / 85 · досвід ${h.xp} / ${xpNeeded(h.level)} · вільні очки: ${h.statPoints}<br>За кожен новий рівень — 5 очок. Спеціалізації на 20, 40, 60 та фінальна форма на 85.</div><div class="stat-grid">${STAT_KEYS.map(k=>`<div class="stat-row"><span>${k}</span><b>${h.stats[k]}</b><button data-stat="${k}" ${h.statPoints<1||h.stats[k]>=99?'disabled':''} aria-label="Підвищити ${k}">+</button></div>`).join('')}</div><h3 class="section-title">Поточні бойові показники</h3><div class="card-grid">${[['HP',d.hp],['SP',d.sp],['ATK',d.atk],['MATK',d.matk],['DEF',d.def],['MDEF',d.mdef],['HIT',d.hit],['FLEE',d.flee],['Критичний шанс',d.crit*100+'%'],['Інтервал атак',d.interval.toFixed(2)+' с']].map(([k,v])=>`<div class="card"><b>${k}</b><p>${typeof v==='number'?v.toFixed(1):v}</p></div>`).join('')}</div><p class="small muted">Це робочі формули поточної версії. Баланс підлягає перевірці грою.</p>`;break;
case'inventory':title='Торба мандрівника';html=`<p class="notice">${h.inventory.length} предметів · ${h.zeny} Z · кожен екземпляр має власний ID та власника. Порівняння враховує характеристики, які реально використовує бій.</p><div class="card-grid">${itemCards(h.inventory)}</div>`;break;
case'shop':title='Крамниця Данила';html=`<p class="notice">Гаманець: ${h.zeny} Z. Торгувати можна лише біля Данила. Коваль має знижку 10%.</p><div class="card-grid">${itemCards(['potion','ether',CLASSES[h.classId].weapon,'armor'].map(template=>({template,id:'Крамниця',owner:h.id})),true)}</div><h3 class="section-title">Продати матеріали</h3><div class="card-grid">${itemCards(h.inventory.filter(i=>ITEM_TEMPLATES[i.template].kind==='material'))||'<p class="empty">Матеріалів ще немає.</p>'}</div>`;break;
case'spec':title='Ваш професійний шлях';let c=CLASSES[h.classId];html=`<p class="notice">${c.name} · ${c.role}<br>Навички витрачають SP та мають окреме відновлення. Нові спеціалізації змінюють поведінку прийомів.</p><div class="card-grid">${c.skills.map(a=>`<div class="card"><span class="icon">${a.icon}</span><h3>${a.name}</h3><p>${a.cost} SP · ${a.cd} с · дальність ${a.range||'на себе'}<br>${a.effect?EFFECTS[a.effect].rule:a.kind==='heal'?'Лікує найбільш пораненого союзника поруч.':a.kind==='burst'?'Два окремі снаряди. Від пострілу можна відійти.':'Активна атака з видимою підготовкою.'}</p></div>`).join('')}</div>${[20,40,60,85].map((level,idx)=>`<h3 class="section-title">${level===85?'Фінальна форма':'Спеціалізація'} · ${level} рівень</h3><div class="card-grid">${BRANCH_RULES[level].map((r,i)=>`<div class="card"><span class="tag">${h.level<level?'Недоступно':h.specs[level]===i?'Обрано ✓':'Доступно'}</span><h3>${level===85?c.final:c.branches[idx][i]}</h3><p>${r.desc}</p><button class="btn" data-spec="${level}" data-index="${i}" ${h.level<level||h.specs[level]!==undefined?'disabled':''}>Обрати шлях</button></div>`).join('')}</div>`).join('')}`;break;
case'map':title='Вербове прикордоння';html=`<p class="notice">Карта допомагає орієнтуватися. Переходи відбуваються біля входів у самій локації; ця панель не телепортує персонажа.</p><div class="map-layout">${[['village','⌂','Орися, крамниця, вогнище. Лісова стежка — на півночі. Катакомби — біля храму на сході.'],['forest','♧','Від входу рухайтеся на північ. Печатки на західній стежці, східній галявині та біля старого дуба.'],['crypt','♜','Увійдіть зі слободи після трьох печаток. Знайдіть важіль, пройдіть ґрати, розбийте захисну печатку.']].map(([id,icon,text])=>`<div class="map-zone ${s.zone===id?'current':''}"><span class="icon">${icon}</span><h3>${ZONES[id].name}</h3><p>${text}</p><span class="tag">${s.zone===id?'Ви тут':id==='crypt'&&s.flags.seals.length<3?'Потрібні 3 печатки':'Сполучена локація'}</span></div>`).join('')}</div><p class="muted">Слобода ↔ ліс · Слобода ↔ катакомби. У кооперативі перехід спільний, після голосування.</p>`;break;
case'quest':title='Повернення світла';html=`<p class="dialogue">«Поки хоч одна іскра не згасла, Вирій пам’ятатиме шлях додому».</p><div class="card-grid">${[['1. Три втрачені печатки',`Ліс: знайдено ${s.flags.seals.length}/3. Печатки лежать біля стежок. Вороги можуть завадити взаємодії.`],['2. Катакомби старого храму','Поверніться до слободи, відкрийте запечатані двері. Знайдіть важіль і відкрийте шлях до вівтаря.'],['3. Варта минулого','Захисна печатка поглинає 80% шкоди Хранителю. Зруйнуйте її, уникайте розломів і кореневих хвиль.'],['4. Серце Оберегу',s.flags.ending?'Розділ завершено. Персональну нагороду отримано.':'Після боса заберіть скриню та відновіть Серце Оберегу.']].map(([title,text])=>`<div class="card"><h3>${title}</h3><p>${text}</p></div>`).join('')}</div>`;break;
case'effects':title='Стани та ефекти';html=`<p class="notice">Ефекти спрацьовують у симуляції. Після закінчення таймера модифікатор зникає; отрута не має зайвого тіку після завершення.</p><div class="effect-list">${Object.entries(EFFECTS).map(([id,e])=>`<div class="card"><b style="color:${e.color}">${e.icon} ${e.name}</b><p>Типово ${e.duration} с · максимум ${e.maxStacks} ${e.maxStacks===1?'заряд':'заряди'}</p><p>${e.rule}</p></div>`).join('')}</div>`;break;
case'help':title='Порадник мандрівника';html=`<div class="card-grid"><div class="card"><h3>Рух</h3><p>ПК: WASD / стрілки або клік по землі. Пробіл — атака, 1/2 — навички, 3 — зілля, E — взаємодія.<br>Телефон: дотик по землі або джойстик зліва; великі дії знизу. Наведення не потрібне.</p></div><div class="card"><h3>Бій</h3><p>Торкніться видимого ворога, щоб наблизитися й почати звичайні атаки. Рух перериває переслідування. Навички активуйте окремо. Снаряди мають час польоту; червоні зони боса потрібно залишати.</p></div><div class="card"><h3>Взаємодія</h3><p>Підійдіть до об’єкта і натисніть «Взаємодія». Поговоріть із Орисею, візьміть стартову скриню. Торговець продає спорядження й купує матеріали. Вогнище відновлює HP/SP, коли ворогів поблизу немає.</p></div><div class="card"><h3>Кооператив</h3><p>Серверна кімната — до 8 гравців. Позначте готовність перед важливою подією. Голосування показує предмет рішення; при рівності вирішує голос лідера. Передача предмета потребує прийняття одержувачем поруч.</p></div></div><button class="btn secondary" data-open="effects">Усі стани й правила →</button><button class="btn secondary" data-open="bestiary">Бестіарій →</button>`;break;
case'bestiary':title='Істоти прикордоння';html=`<div class="card-grid">${Object.entries(ENEMIES).map(([id,e])=>`<article class="card"><span class="tag">${e.boss?'БОС':'Рів. '+e.level}</span><h3>${e.name}</h3><p>${e.role}<br>HP ${e.hp} · ATK ${e.atk} · DEF ${e.def} · MDEF ${e.mdef}<br>Дальність ${e.range} · період ${e.period} с</p></article>`).join('')}</div>`;break;
case'coop':showCoop();return;
case'menu':title='Налаштування пригоди';html=`<p class="notice">${session.mode==='local'?'Локальний режим: збереження версії 2 на цьому пристрої. Старе збереження v1 не видаляється.':'Мережевий режим: стан та інвентар зберігає авторитетний сервер. Локальний JSON не імпортується в мережеву економіку.'}</p><button class="btn" id="export-save" ${session.mode==='online'?'disabled':''}>Експортувати збереження</button><label class="btn secondary" ${session.mode==='online'?'hidden':''}>Імпортувати<input id="import-save" type="file" accept="application/json" hidden></label><button class="btn secondary" id="character-menu">Екран персонажа</button><p class="small muted">Нова гра замінить лише поточне локальне збереження v2 після вибору класу. Перед цим можна експортувати прогрес.</p><button class="btn secondary" data-open="help">Керування й поради</button><p class="small muted">Версія 0.2 · Phaser 3.90 · один регіон, три з’єднані зони. Локальна гра не є MMO. Розгорнутий статичний сайт не містить сервера кімнат.</p>`;break;
}show(title,html);}
function showCoop(){panel='coop';let h=hero(),online=session?.mode==='online',s=session?.state;if(online){show('Ваша кооперативна кімната',`<div class="notice">Авторитетний сервер · ${session.connected?'підключено':'перепідключення…'} · подія #${s.eventSeq} · раунд ${s.round}<br>Код кімнати: <b class="coop-code">${session.room}</b></div><p class="small muted">Інший гравець відкриває цей самий клієнт, обирає клас і вводить цей код та адресу сервера. Сесія прив’язана до вкладки; її можна відновити після розриву.</p><div class="card-grid">${Object.values(s.players).map(p=>`<div class="card"><h3>${escape(p.name)} ${p.id===s.leader?'♛':''}</h3><p>${CLASSES[p.classId].name} · ${p.online?'у мережі':'від’єднано'} · ${p.ready?'готовий ✓':'не готовий'}</p></div>`).join('')}</div><button class="btn" id="ready-toggle">${h.ready?'Скасувати готовність':'Я готовий'}</button><h3 class="section-title">Передачі предметів</h3>${s.offers.filter(o=>o.status==='pending').map(o=>`<div class="trade-row"><span>${escape(o.name)}<br><small>${escape(s.players[o.from]?.name)} → ${escape(s.players[o.to]?.name)}</small></span>${o.to===h.id?`<button class="btn" data-accept="${escape(o.id)}">Прийняти</button>`:'<span class="tag">Очікування · до 30 с</span>'}</div>`).join('')||'<p class="muted">Немає активних пропозицій. Відкрийте торбу, щоб передати власний неспоряджений предмет.</p>'}`);return;}
show('Кооператив · до 8 гравців',`<p class="notice">${serverAvailable?'Сервер доступний на поточній адресі.':'У цій публікації працює локальна гра. Для справжнього кооперативу потрібен запущений сервер із репозиторію: npm install → npm start. Можна вказати адресу доступного сервера нижче.'}</p><p class="small muted">Кімната має спільних ворогів і переходи, персональний лут та підтверджувану передачу речей. Сервер обчислює шкоду, дистанції та нагороди. Прогрес соло не переноситься в мережеву економіку.</p><div class="field"><label>Ваше ім’я<br><input id="coop-name" value="${escape(h?.name||sessionStorage.getItem('vyriy-name')||'Мандрівник')}" maxlength="22"></label><label>Клас<br><select id="coop-class">${Object.entries(CLASSES).map(([id,c])=>`<option value="${id}" ${id===(h?.classId||selectedClass)?'selected':''}>${c.name}</option>`).join('')}</select></label></div><div class="field"><label>Адреса сервера<br><input id="server-url" type="url" value="${escape(location.origin)}" placeholder="https://your-server.example"></label><label>Код кімнати (порожній — нова)<br><input id="room-code" maxlength="8" autocomplete="off" placeholder="a1b2c3d4"></label></div><button class="btn" id="connect-server">Увійти в кімнату</button><button class="btn secondary" id="back-local">${h?'Повернутися до гри':'Вибір персонажа'}</button><p class="small muted">Для доступу з іншого пристрою сервер повинен мати HTTPS/WSS та дозволений Origin. Платний хостинг не підключено.</p>`);}
function refreshPanel(){if(['hero','inventory','shop','spec','coop'].includes(panel))setTimeout(()=>open(panel),session?.mode==='online'?220:0);}
function updateHUD(s,id,time){if(time-lastHUD<130)return;lastHUD=time;let h=s.players[id];if(!h)return;let d=derive(h),c=CLASSES[h.classId];if(session.mode==='online')$('save-status').textContent='Стан зберігає сервер · подія #'+s.eventSeq;$('hero-name').textContent=h.name;$('hero-level').textContent='РІВ. '+h.level;$('hero-art').setAttribute('style',artStyle(h.classId));$('hp-value').textContent=Math.ceil(h.hp)+' / '+Math.ceil(d.hp);$('hp-fill').style.width=Math.max(0,h.hp/d.hp*100)+'%';$('sp-value').textContent=Math.floor(h.sp)+' / '+Math.ceil(d.sp);$('sp-fill').style.width=h.sp/d.sp*100+'%';$('xp-fill').style.width=h.xp/xpNeeded(h.level)*100+'%';$('location-name').textContent=ZONES[s.zone].name;$('mode-label').textContent=session.mode==='local'?'Локальний режим · один герой':`Кімната ${session.room} · ${session.connected?'підключено':'перепідключення…'}`;$('quest-heading').textContent=s.flags.ending?'Оберіг знову сяє':s.flags.seals.length<3?'Три втрачені печатки':s.flags.boss?'Серце Оберегу':'Під старим храмом';$('quest-objective').textContent=s.flags.ending?'Розділ завершено. Прикордоння врятовано.':s.flags.seals.length<3?`Печатки лісу: ${s.flags.seals.length} / 3`:s.flags.boss?'Торкніться вівтаря в катакомбах':!s.flags.switch?'Відкрийте катакомби та знайдіть важіль':'Розбийте захисну печатку. Здолайте Хранителя.';$('party-hud').innerHTML=Object.values(s.players).filter(p=>p.id!==id).map(p=>`<div class="party-member"><span>${p.id===s.leader?'♛ ':''}${escape(p.name)}</span><span>${p.online?Math.ceil(p.hp)+' HP':'Від’єднано'}</span></div>`).join('');for(let i=0;i<2;i++){let b=$('skill'+i),sk=c.skills[i];b.querySelector('b').textContent=sk.icon;b.querySelector('span').textContent=sk.name;b.querySelector('em').textContent=h.cooldowns[sk.id]>0?Math.ceil(h.cooldowns[sk.id]):'';b.setAttribute('aria-label',sk.name+' · '+sk.cost+' SP');}let potions=h.inventory.filter(i=>i.template==='potion').length;$('potion').querySelector('span').textContent='Зілля ×'+potions;$('potion').querySelector('em').textContent=h.cooldowns.potion>0?Math.ceil(h.cooldowns.potion):'';$('bag-count').textContent=h.inventory.length;$('attack').classList.toggle('selected',h.auto);let near=nearestObject();$('interact').classList.toggle('near',!!near);$('interact').querySelector('span').textContent=near?near.kind==='portal'?'Перейти':near.kind==='camp'?'Відпочити':near.kind==='chest'?'Відкрити':'Взаємодія':'Взаємодія';$('interact').setAttribute('aria-label',near?'Взаємодія: '+near.name:'Взаємодія');$('status-hud').innerHTML=(h.effects||[]).map(e=>`<button data-open="effects" aria-label="${EFFECTS[e.id]?.name||e.id}: ${Math.ceil(e.left)} секунд" style="color:${EFFECTS[e.id]?.color||'#fff'}">${EFFECTS[e.id]?.icon||'?'}<small>${Math.ceil(e.left)}с ${e.stacks>1?'×'+e.stacks:''}</small></button>`).join('');let target=s.enemies.find(e=>e.id===h.target&&!e.dead);$('target-hud').hidden=!target;if(target){$('target-hud').innerHTML=`${target.boss?'♛ ':''}${escape(target.name)} · ${target.level}<div><i style="width:${Math.max(0,target.hp/target.maxHp*100)}%"></i></div><small>${escape(target.role)}</small>`;}$('cast-hud').hidden=!h.cast;if(h.cast){$('cast-label').textContent=c.skills[h.cast.index].name;$('cast-fill').style.width=(1-h.cast.left/h.cast.total)*100+'%';}$('death-hud').hidden=!h.dead;if(h.dead){$('death-reason').textContent=h.deathReason||'Загинув у бою';if($('modal').open)close();}$('vote-hud').hidden=!s.vote;if(s.vote){$('vote-title').textContent=s.vote.label;let yes=Object.values(s.vote.ballots).filter(v=>v==='yes').length,no=Object.values(s.vote.ballots).filter(v=>v==='no').length;$('vote-count').textContent=`За ${yes} · проти ${no} · ще ${Math.max(0,Math.ceil(s.vote.expires-s.clock))} с. При рівності вирішує лідер.`;$('vote-yes').disabled=!!s.vote.ballots[id];$('vote-no').disabled=!!s.vote.ballots[id];}if(session.error){toast(session.error);session.error=null;}}
function event(ev){if(!session)return;if(ev.actor&&ev.actor!==session.id&&['loot','rest','death'].includes(ev.type))return;if(ev.text){logs.unshift(ev.text);logs=logs.slice(0,4);$('event-log').innerHTML=logs.map(t=>`<p>${escape(t)}</p>`).join('');if(['telegraph','story','ending','level'].includes(ev.type))toast(ev.text);if(ev.type==='ending')open('quest');}}
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.class){selectedClass=d.class;let name=$('character-name')?.value;sessionStorage.setItem('vyriy-name',name||'Мандрівник');choose();return;}if(d.close!==undefined){close();return;}if(d.open){open(d.open);return;}if(d.stat){command('stat',{stat:d.stat});refreshPanel()}if(d.spec){command('spec',{level:+d.spec,index:+d.index});refreshPanel()}if(d.equip){command('equip',{id:d.equip});refreshPanel()}if(d.use){command('use',{id:d.use});refreshPanel()}if(d.socket){command('socket',{card:d.socket});refreshPanel()}if(d.buy){command('buy',{template:d.buy});refreshPanel()}if(d.sell){command('sell',{id:d.sell});refreshPanel()}if(d.offer){let others=Object.values(session.state.players).filter(p=>p.id!==session.id&&p.online&&Math.hypot(p.x-hero().x,p.y-hero().y)<4);panel='trade';show('Передати предмет',`<p class="notice">Одержувач має прийняти пропозицію протягом 30 с. Предмет зберігає свій ID та отримує нового власника один раз.</p>${others.map(p=>`<button class="btn" data-transfer="${escape(d.offer)}" data-to="${escape(p.id)}">${escape(p.name)}</button>`).join('')||'<p>Немає союзників поруч.</p>'}`)}if(d.transfer){command('offer',{item:d.transfer,to:d.to});open('coop')}if(d.accept){command('offerAccept',{id:d.accept});refreshPanel()}switch(b.id){case'modal-close':if(panel!=='create')close();break;case'start-local':startLocal();break;case'continue-local':startLocal(true);break;case'start-coop-menu':showCoop();break;case'back-local':session?close():choose();break;case'connect-server':{let base=$('server-url').value.trim(),room=$('room-code').value.trim(),name=$('coop-name').value.trim(),classId=$('coop-class').value;try{let u=new URL(base);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('Потрібна HTTP(S)-адреса сервера');b.disabled=true;let next=await RemoteSession.join(base,room,classId,name);session?.save();session?.close();session=next;close();toast('Кімнату створено. Код: '+session.room);}catch(err){b.disabled=false;toast(err.message)}break;}case'hero-open':open('hero');break;case'inventory-open':open('inventory');break;case'spec-open':open('spec');break;case'world-map':open('map');break;case'coop-open':open('coop');break;case'menu-open':open('menu');break;case'help-open':open('help');break;case'quest-open':open('quest');break;case'attack':case'skill0':case'skill1':case'potion':case'interact':action(b.id);break;case'respawn':command('respawn');break;case'vote-yes':command('vote',{value:'yes'});break;case'vote-no':command('vote',{value:'no'});break;case'ready-toggle':command('ready',{value:!hero().ready});refreshPanel();break;case'character-menu':session.save();if(session.mode==='online')session.close();choose();break;case'export-save':{let url=URL.createObjectURL(new Blob([JSON.stringify(session.state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='vyriy-save-v2.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);break;}}});
$('modal-body').addEventListener('change',async e=>{if(e.target.id==='import-save'){try{let saved=validateImported(JSON.parse(await e.target.files[0].text()));session?.close();session=new LocalSession(saved);session.save();close();toast('Збереження v2 відновлено')}catch(err){toast('Не вдалося імпортувати: '+err.message)}}});$('modal').addEventListener('cancel',e=>{if(panel==='create')e.preventDefault();else panel=null});$('modal').addEventListener('close',()=>{if(panel!=='create')panel=null});
let joyPointer=null;$('joystick').addEventListener('pointerdown',e=>{joyPointer=e.pointerId;$('joystick').setPointerCapture(e.pointerId);updateJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(joyPointer===e.pointerId)updateJoy(e)});function updateJoy(e){let r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.max(1,Math.hypot(dx,dy)/28);joystick={x:dx/len/28,y:dy/len/28};$('joy-knob').style.transform=`translate(${dx/len}px,${dy/len}px)`}for(let type of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(type,()=>{joystick={x:0,y:0};joyPointer=null;$('joy-knob').style.transform='';});
setInterval(()=>{if(session?.mode==='local'&&!document.hidden){$('save-status').textContent=session.save()?'Збережено · тільки на цьому пристрої':'Збереження недоступне — експортуйте прогрес';}},5000);window.addEventListener('pagehide',()=>session?.save());document.addEventListener('visibilitychange',()=>{if(document.hidden&&session?.mode==='local')session.save()});
async function boot(){sceneHandle=launchScene($('scene'),()=>session,{command,toast,interact,action,event,updateHUD,joystick:()=>joystick});try{let r=await fetch('/api/health',{signal:AbortSignal.timeout(1500)});serverAvailable=r.ok&&(await r.json()).maxPlayers===8}catch{}try{session=await RemoteSession.resume()}catch{}if(session){toast('Мережеву сесію відновлено');return;}choose();}boot();
